package org.medsupply;
import java.util.List;import java.util.Map;import java.util.LinkedHashMap;
public final class JsonTest {public static void main(String[] args){String json="{\"a\":\"x\",\"n\":3,\"b\":true,\"z\":null,\"arr\":[1,2,{\"k\":\"v\"}]}";Map<String,Object> m=Json.asMap(Json.parse(json));check("x".equals(Json.str(m,"a")),"a");check("3".equals(Json.str(m,"n")),"n");check(Boolean.TRUE.equals(m.get("b")),"b");check(m.containsKey("z")&&m.get("z")==null,"null");List<Object> arr=Json.asList(m.get("arr"));check(arr.size()==3&&"v".equals(Json.str(Json.asMap(arr.get(2)),"k")),"nesting");Map<String,Object> out=new LinkedHashMap<String,Object>();out.put("q",Double.valueOf(5));out.put("s","a\"b\\c\n");check("{\"q\":5,\"s\":\"a\\\"b\\\\c\\n\"}".equals(Json.write(out)),"write");check(Json.asMap(Json.parse("{\"device\":{\"gmdnTerms\":{\"gmdn\":[{\"name\":\"stent\"}]}}}" )).size()==1,"GUDID shape");System.out.println("JsonTest: PASS");}private static void check(boolean c,String s){if(!c)throw new AssertionError("Failed: "+s);}}
